-- Seed pos_item_categories from Nik's hand-built monthly split.
--
-- Generated by scripts/seed-item-categories.mjs
--   raw export : D:/coin/SaleData_20260908_194017.xls
--   hand-built : D:/พี่น้อง/69/CS/69-08SaleData.xlsx
--   period     : สิงหาคม 2569
--
-- 523 products. Coverage check passed: every one of the
-- 523 distinct products in the raw export has a category.
--
-- ── THIS IS A ONE-TIME SEED, AND THE FILE ENFORCES THAT ITSELF ──────────
--
-- It refuses to run if pos_item_categories already holds ANY row. That is
-- not caution for its own sake: a re-run against a later month's files
-- would insert every product new since August with a category decided by
-- the seed's group rules rather than by a person — silently bypassing the
-- review the screen exists to provide. ON CONFLICT DO NOTHING protects rows
-- that already exist; it does nothing to protect rows that do not yet.
--
-- New products are classified ON THE SCREEN at /owner/accounting/coffee-items,
-- where they surface as ใหม่ until someone picks a category. Never by
-- re-seeding.
--
-- PROVENANCE. This file does not set reviewed_by, so every seeded row has
-- reviewed_by IS NULL. A row a human classified on the screen carries their
-- UUID. That is the only way to tell a seed decision from a human one later,
-- and it is deliberate — do not backfill reviewed_by on these rows.

BEGIN;

DO $$
DECLARE
  existing INTEGER;
BEGIN
  SELECT count(*) INTO existing FROM public.pos_item_categories;
  IF existing <> 0 THEN
    RAISE EXCEPTION
      'ABORTED: pos_item_categories already holds % rows. This seed is one-time. '
      'Nothing has been written. New products are classified on the screen at '
      '/owner/accounting/coffee-items (they appear as ใหม่ until categorised) — '
      'do not re-seed to add them.', existing;
  END IF;
END $$;

ON CONFLICT (pos_product_name) DO NOTHING;

COMMIT;

